# TODO: Update module docstring

from taf.internal.managedobject import ManagedObject
from .exceptions import (EdaemonSetupFailure,
                         EgateSetupFailure)
from .remote_entities import RemoteProcess
from . import logger


class UecRemoteProcess(ManagedObject):
    """ Edaemon.
    Methods:
    - :meth:`setup`: prepares and starts edaemon process
    """
    # TODO: Rewrite class docstring
    # TODO: Method docstrings

    def __init__(self, ssh_connection, directory, port, sudo_password=None, nostats=False, *args, **kwargs):
        super(UecRemoteProcess, self).__init__(**kwargs)
        self.add_prerequisite(ssh_connection)

        command = self.COMMAND_TEMPLATE.format(port=port)

        self._process = RemoteProcess(ssh_connection, command, directory,
                                      sudo=self.WITH_SUDO,
                                      password=sudo_password, port=port)
        self.logger = logger.getChild(self.__class__.__name__)
        self._process.logger = self.logger

    def _setup(self):
        """
        kill the process if it exist and start a new one
        """
        self._process.kill_processes_that_occupies_given_port()
        exit_code, _, _ = self._process.start(wait=self.WAIT_FOR_EXEC_END)
        if exit_code != 0:
            exc_msg = "{} failed to initialize.".format(self.COMMON_NAME)
            raise self.SETUP_FAILURE_EXCEPTION(exc_msg)
        log_msg = "{} startup done.".format(self.COMMON_NAME)
        self.logger.info(log_msg)

    def _teardown(self):
        """
        kill the process
        """
        self.logger.debug('Tearing down {}'.format(self.COMMON_NAME))
        self._process.kill_processes_that_occupies_given_port()


class Edaemon(UecRemoteProcess):
    """ Edaemon.
    Methods:
    - :meth:`setup`: prepares and starts edaemon process
    """
    # NOTE: This process uses sudo as a command prefix.
    COMMAND_TEMPLATE = './edaemon --port {port}'
    COMMON_NAME = "Edaemon"
    SETUP_FAILURE_EXCEPTION = EdaemonSetupFailure
    WITH_SUDO = True
    WAIT_FOR_EXEC_END = True

    # TODO: Rewrite class docstring


class Egate(UecRemoteProcess):
    """ This class manages (runs / kills) Egate process on a remote host.
    Methods:
    - :meth:`setup`: kill Egate process running on the previously specified
    port and start a new one from scratch.
    """
    COMMAND_TEMPLATE = './egate --root --port {port}'
    COMMON_NAME = "Egate"
    SETUP_FAILURE_EXCEPTION = EgateSetupFailure
    WITH_SUDO = False
    WAIT_FOR_EXEC_END = True

    # TODO: Update class docstring.
